</script>
<template><Head title="Admin login" /><main class="login-page"><section class="login-intro"><a href="/" class="admin-brand"><span>TGS</span><small>Tax & General<br>Services</small></a><div><p class="eyebrow">Private administration</p><h1>Clear oversight.<br>Confident decisions.</h1><p>Manage appointments, availability, and your practice in one composed workspace.</p></div><small>© Tax & General Services</small></section><section class="login-panel"><form class="login-form" @submit.prevent="submit"><p class="eyebrow">Secure access</p><h2>Welcome back</h2><p>Sign in to your administration area.</p><label>Email<input v-model="form.email" type="email" autocomplete="email" placeholder="you@example.com"><small v-if="form.errors.email">{{ form.errors.email }}</small></label><label>Password<input v-model="form.password" type="password" autocomplete="current-password" placeholder="••••••••"><small v-if="form.errors.password">{{ form.errors.password }}</small></label><label class="remember"><input v-model="form.remember" type="checkbox"> Remember me</label><button class="button primary" :disabled="form.processing">{{ form.processing ? 'Logging in…' : 'Login' }} <span>→</span></button></form></section></main></template>
